@@ -0,0 +1,40 @@
+// Picks the response language from a request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+/** The supported language a request's `Accept-Language` prefers (q-values and region tags honored), else `fallback`. */
+export function requestLanguage(headers, fallback) {
+  const name = Object.keys(headers ?? {}).find((k) => k.toLowerCase() === "accept-language");
+  const raw = name === undefined ? "" : headers[name];
+  const header = Array.isArray(raw) ? raw.join(",") : String(raw ?? "");
+  // Per supported language: the best q among its ranges ("ko", "ko-KR"); "*" covers the rest.
+  const named = new Map();
+  let wildcard = null;
+  header.split(",").forEach((part, pos) => {
+    const [range, ...params] = part.split(";").map((s) => s.trim().toLowerCase());
+    if (!/^(\*|[a-z]{1,8}(-[a-z0-9]{1,8})*)$/.test(range)) return;
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.*)$/.exec(p);
+      if (!m) continue;
+      if (!/^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1])) return;
+      q = Number(m[1]);
+    }
+    if (range === "*") {
+      if (!wildcard || q > wildcard.q) wildcard = { q, pos };
+      return;
+    }
+    const lang = range.split("-")[0];
+    if (!LANGUAGES.includes(lang)) return;
+    const seen = named.get(lang);
+    if (!seen || q > seen.q) named.set(lang, { q, pos });
+  });
+  let best = null;
+  for (const lang of LANGUAGES) {
+    const hit = named.get(lang) ?? wildcard;
+    if (!hit || hit.q <= 0) continue;
+    const better =
+      !best || hit.q > best.q || (hit.q === best.q && (hit.pos < best.pos || (hit.pos === best.pos && lang === fallback)));
+    if (better) best = { lang, q: hit.q, pos: hit.pos };
+  }
+  return best ? best.lang : fallback;
+}
